import Foundation

extension FinanceGuides {
    static let taxes = DirectoryGuide(
        cardSummary: .init(ukrainian: "Коли подавати декларацію, іноземний дохід і Bescheid", german: "Abgabepflicht, Auslandseinkünfte und Bescheid"),
        introduction: .init(ukrainian: "Спершу визначте, чи подання добровільне або обов’язкове. Форма, строк і врахування доходів з України залежать від ваших конкретних обставин.", german: "Klären Sie zuerst, ob die Erklärung freiwillig oder verpflichtend ist. Formular, Frist und Behandlung ukrainischer Einkünfte hängen vom Einzelfall ab."),
        sections: [
            .init("obligation", "list.bullet.rectangle", "Визначте обов’язок подання", "Abgabepflicht klären", "Якщо весь рік був один австрійський роботодавець, часто йдеться про добровільну Arbeitnehmerveranlagung. Кілька роботодавців одночасно, додаткові доходи чи дохід за кордоном можуть створити обов’язок подати декларацію. Перевірте умови BMF для свого року й виду доходу до того, як орієнтуватися на п’ятирічний строк.", "Bei nur einem österreichischen Arbeitgeber geht es oft um eine freiwillige Arbeitnehmerveranlagung. Gleichzeitige mehrere Arbeitgeber, Nebeneinkünfte oder Auslandseinkünfte können eine Pflicht auslösen. BMF-Regeln für Ihr Jahr und Ihre Einkunftsart prüfen, bevor Sie von der Fünfjahresfrist ausgehen.", source: mandatoryTax),
            .init("records", "doc.text", "Зберіть підтвердження, але не надсилайте все одразу", "Belege sammeln, nicht ungefragt einsenden", "У FinanzOnline перевірте передані Lohnzettel і свій IBAN. Зберіть підтвердження витрат, які справді можуть бути відраховані, наприклад на робочі засоби або професійне навчання. BMF радить не додавати чеки без запиту, але зберігати підтвердження витрат сім років для можливої перевірки.", "In FinanzOnline übermittelte Lohnzettel und den eigenen IBAN prüfen. Nachweise für tatsächlich mögliche Abzüge wie Arbeitsmittel oder berufliche Weiterbildung sammeln. Laut BMF Belege nicht ungefragt mitschicken, aber sieben Jahre für eine mögliche Prüfung aufbewahren.", source: taxExpenses),
            .init("abroad", "globe.europe.africa", "Окремо розберіть доходи з України", "Einkünfte aus der Ukraine getrennt prüfen", "Запишіть вид, суму, період і вже сплачений податок для зарплати, підприємництва, оренди чи пенсії з-за кордону. Між Австрією й Україною є договір про уникнення подвійного оподаткування, але він не означає автоматичного звільнення будь-якого доходу. Податкове резидентство й статті договору перевіряйте для кожного виду доходу; за потреби зверніться до податкового фахівця.", "Art, Betrag, Zeitraum und bereits gezahlte Steuer für ausländischen Lohn, Selbständigkeit, Vermietung oder Pension getrennt erfassen. Zwischen Österreich und der Ukraine besteht ein Doppelbesteuerungsabkommen; es befreit aber nicht automatisch jedes Einkommen. Ansässigkeit und einschlägigen Vertragsartikel je Einkunftsart prüfen, gegebenenfalls mit Steuerberatung.", source: taxTreaty),
            .init("form", "checklist", "Оберіть правильну форму", "Passendes Formular wählen", "Для Arbeitnehmerveranlagung використовуйте L1 через FinanzOnline або на папері; за наявності закордонного доходу перевірте додаток L1i. Для самостійної діяльності може знадобитися декларація E1 замість простого L1. Не подавайте навмання: у Finanzamt уточніть, яка форма відповідає вашому доходу, і збережіть підтвердження подання.", "Für die Arbeitnehmerveranlagung L1 über FinanzOnline oder auf Papier nutzen; bei Auslandseinkünften die Beilage L1i prüfen. Selbständige benötigen möglicherweise eine E1-Erklärung statt eines einfachen L1. Formular beim Finanzamt anhand der eigenen Einkünfte klären und Einreichungsbestätigung aufbewahren.", source: taxDeadline),
            .init("deadline", "calendar", "Не сплутайте строки", "Fristen nicht verwechseln", "Добровільну Arbeitnehmerveranlagung за 2025 рік можна подати до 31.12.2030. Якщо подання обов’язкове, загальний строк — до 30 квітня наступного року на папері або до 30 червня онлайн; індивідуальне повідомлення Finanzamt може встановити інший строк. Не чекайте п’ять років, якщо у вас обов’язок подати декларацію.", "Die freiwillige Arbeitnehmerveranlagung für 2025 kann bis 31.12.2030 eingereicht werden. Bei Pflichtveranlagung gilt grundsätzlich der 30. April des Folgejahres auf Papier oder der 30. Juni online; eine individuelle Finanzamt-Mitteilung kann anderes vorgeben. Bei Abgabepflicht nicht fünf Jahre warten.", source: mandatoryTax),
            .init("decision", "envelope.open", "Перевірте рішення й строк оскарження", "Bescheid und Beschwerdefrist prüfen", "Після отримання Bescheid звірте дохід, враховані витрати й суму повернення або доплати. Якщо рішення помилкове, зазвичай є місяць від вручення для письмової Beschwerde; зазначте, що саме оскаржуєте й яку зміну просите. Скарга сама по собі не зупиняє строк сплати донарахування: за потреби окремо запитайте про Aussetzung der Einhebung.", "Nach dem Bescheid Einkommen, berücksichtigte Abzüge und Guthaben bzw. Nachzahlung prüfen. Bei Fehlern bleibt grundsätzlich ein Monat ab Zustellung für eine schriftliche Beschwerde mit angefochtenem Punkt und gewünschter Änderung. Eine Beschwerde stoppt die Zahlungsfrist nicht automatisch; bei Bedarf Aussetzung der Einhebung gesondert beantragen.", source: taxAppeal)
        ], sources: [mandatoryTax, taxExpenses, taxTreaty, taxDeadline, taxAppeal]
    )
}
